-- ROOT ONLY: one AAPL NY-day page; no provider fetch, budget increase, cron enable or global wake.
-- Retains current four P01 handlers by immutable delegation and leaves P02 unchanged.
-- New ACQUIRE task is parked until root explicitly releases it after current admission review.
BEGIN;
SET LOCAL lock_timeout='3s';SET LOCAL statement_timeout='10s';
SELECT pg_advisory_xact_lock(2026083000261022);
DO $admit$
DECLARE bundle text;vers jsonb;test_evidence jsonb;deploy_evidence jsonb;wrapper_hashes jsonb;legacy_hashes jsonb;ad record;new_fn regprocedure;tid uuid;p02_before jsonb;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.acquisition_control WHERE singleton AND owner_id='top3000-recovery-20261023-root-4b1314bcb5c2' AND owner_fence=2 AND stop_generation=0 AND enabled AND NOT stopped AND hold_reason IS NULL AND admitted_until>clock_timestamp()) THEN RAISE EXCEPTION 'OWNER_STOP_OR_ADMISSION_CHANGED';END IF;
 IF EXISTS(SELECT 1 FROM cron.job WHERE jobid=596 AND active) THEN RAISE EXCEPTION 'CRON_596_MUST_BE_INACTIVE_DURING_MINUTE_TRANSFER';END IF;
 IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_task WHERE family_id='P01' AND status='LEASED') THEN RAISE EXCEPTION 'P01_LEASE_MUST_FINISH_BEFORE_WRAPPER_TRANSFER';END IF;
 IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_provider_lease l JOIN population_top3000_202608_202609_v1.pipeline_attempt a USING(attempt_id) JOIN population_top3000_202608_202609_v1.pipeline_task t USING(task_id) WHERE t.family_id='P01' AND l.released_at IS NULL) THEN RAISE EXCEPTION 'P01_PROVIDER_EFFECT_REQUIRES_RECONCILIATION';END IF;
 IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_control WHERE singleton AND shared_scheduler_verified AND budget_evidence->>'provider_admissions_allowed'='true' AND budget_evidence->'allowed_providers' ? 'Massive') THEN RAISE EXCEPTION 'CURRENT_MASSIVE_RESOURCE_ADMISSION_REQUIRED';END IF;
 PERFORM population_top3000_202608_202609_v1.massive_minute_resource_guard_v1();
 IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.massive_minute_page_v1) OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_task WHERE family_id='P01' AND payload->>'kind'='MASSIVE_MINUTE_PILOT_V1') THEN RAISE EXCEPTION 'MINUTE_LANE_ALREADY_STARTED_RECONCILE_PRESERVED_PROGRESS';END IF;
 bundle:=population_top3000_202608_202609_v1.massive_minute_bundle_sha256_v1();
 SELECT jsonb_object_agg(stage,encode(sha256(convert_to(pg_get_functiondef(('population_top3000_202608_202609_v1.massive_minute_route_'||lower(stage)||'_v1(uuid,text)')::regprocedure),'UTF8')),'hex')) INTO wrapper_hashes FROM (VALUES('ACQUIRE'),('NORMALIZE'),('DERIVE'),('VALIDATE')) x(stage);
 SELECT jsonb_object_agg(stage,function_sha256) INTO legacy_hashes FROM population_top3000_202608_202609_v1.pipeline_adapter WHERE family_id='P01' AND stage IN('ACQUIRE','NORMALIZE','DERIVE','VALIDATE');
 IF (SELECT count(*) FROM jsonb_object_keys(legacy_hashes))<>4 THEN RAISE EXCEPTION 'ALL_FOUR_CURRENT_LEGACY_P01_ADAPTERS_REQUIRED';END IF;
 SELECT details INTO test_evidence FROM population_top3000_202608_202609_v1.pipeline_event WHERE event='MASSIVE_MINUTE_PILOT_ROLLBACK_VERIFIED' AND details->>'result'='PASS' AND details->>'minute_bundle_sha256'=bundle AND details->'tested_function_sha256'=wrapper_hashes AND details->'preserved_legacy_function_sha256'=legacy_hashes AND details->>'preserved_alpaca_bundle_sha256'=population_top3000_202608_202609_v1.alpaca_sip_code_hash_v1() AND details->>'live_provider_requested'='false' AND details->>'provider_accuracy_verified'='false' AND details->>'original_retained_p01_delegation_preserved'='true' AND details->>'p02_unchanged'='true' ORDER BY at DESC LIMIT 1;
 IF test_evidence IS NULL THEN RAISE EXCEPTION 'ACTUAL_CURRENT_MINUTE_AND_PRESERVED_P01_P02_ROLLBACK_EVIDENCE_REQUIRED';END IF;
 SELECT details INTO deploy_evidence FROM population_top3000_202608_202609_v1.pipeline_event WHERE event='MASSIVE_MINUTE_WORKER_DEPLOYED_VERIFIED' AND details->>'result'='PASS' AND details->>'slug'='population-top3000-minute-v1' AND details->>'worker_sha256'='ccf92df047ed9af51fbb2830fd1772c0ba8615e4e7a09ee53194c36ca96cc8c2' AND details->>'invalid_token_http_status'='403' AND details->>'provider_requests_during_auth_probe'='0' ORDER BY at DESC LIMIT 1;
 IF deploy_evidence IS NULL THEN RAISE EXCEPTION 'CURRENT_MINUTE_WORKER_DEPLOYMENT_AND_AUTH_EVIDENCE_REQUIRED';END IF;
 IF position('population-top3000-minute-v1' IN pg_get_functiondef('population_top3000_202608_202609_v1.pipeline_dispatch_edge_v1(uuid,text,text)'::regprocedure))=0 THEN RAISE EXCEPTION 'ROOT_REVIEWED_MINUTE_EDGE_ALLOWLIST_REQUIRED';END IF;
 SELECT jsonb_build_object('adapters',(SELECT jsonb_agg(to_jsonb(x) ORDER BY stage) FROM population_top3000_202608_202609_v1.pipeline_adapter x WHERE family_id='P02'),'binding',(SELECT to_jsonb(x) FROM population_top3000_202608_202609_v1.pipeline_family_binding x WHERE family_id='P02')) INTO p02_before;
 FOR ad IN SELECT * FROM population_top3000_202608_202609_v1.pipeline_adapter WHERE family_id='P01' AND stage IN('ACQUIRE','NORMALIZE','DERIVE','VALIDATE') LOOP
  IF NOT ad.enabled OR ad.function_sha256 IS DISTINCT FROM encode(sha256(convert_to(pg_get_functiondef(ad.function_oid),'UTF8')),'hex') OR ad.producer_revision='massive-minute-aapl-20260908-v1' THEN RAISE EXCEPTION 'CURRENT_LEGACY_ADAPTER_NOT_VERIFIED_OR_ALREADY_ROUTED';END IF;
  INSERT INTO population_top3000_202608_202609_v1.massive_minute_legacy_adapter_v1(stage,function_oid,function_sha256,registration_evidence) VALUES(ad.stage,ad.function_oid,ad.function_sha256,jsonb_build_object('original_adapter',to_jsonb(ad),'actual_rollback_test',test_evidence,'preserved_without_function_mutation',true)) ON CONFLICT(stage) DO NOTHING;
  IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.massive_minute_legacy_adapter_v1 WHERE stage=ad.stage AND function_oid=ad.function_oid AND function_sha256=ad.function_sha256) THEN RAISE EXCEPTION 'LEGACY_REGISTRY_CONFLICT';END IF;
  new_fn:=('population_top3000_202608_202609_v1.massive_minute_route_'||lower(ad.stage)||'_v1(uuid,text)')::regprocedure;
  UPDATE population_top3000_202608_202609_v1.pipeline_adapter SET function_oid=new_fn::oid,function_sha256=wrapper_hashes->>ad.stage,resource_class=CASE WHEN ad.stage='ACQUIRE' THEN 'PROVIDER' ELSE 'DATABASE' END,provider=NULL,
   reviewed_test_evidence=jsonb_build_object('actual_sql_test',test_evidence,'worker_deployment',deploy_evidence,'legacy_adapter_captured',to_jsonb(ad),'provider_selection','PER_TASK_HASH_BOUND_HANDLER_AND_EXACT_PROVIDER_LEASE','supported_providers',jsonb_build_array('Alpaca','Massive'),'admission','ONE_AAPL_20260908_SOURCE_PAGE_PENDING_CONTROLLER_RELEASE','company_population_verified',false),producer_revision='massive-minute-aapl-20260908-v1',expected_batch_seconds=45 WHERE family_id='P01' AND stage=ad.stage;
 END LOOP;
 IF p02_before IS DISTINCT FROM (SELECT jsonb_build_object('adapters',(SELECT jsonb_agg(to_jsonb(x) ORDER BY stage) FROM population_top3000_202608_202609_v1.pipeline_adapter x WHERE family_id='P02'),'binding',(SELECT to_jsonb(x) FROM population_top3000_202608_202609_v1.pipeline_family_binding x WHERE family_id='P02'))) THEN RAISE EXCEPTION 'MINUTE_P02_CHANGE_NOT_AUTHORISED';END IF;
 vers:=jsonb_build_object('scope_sha256','8e6ca1178f03822c34bb1b339818b34dcfdbf2a8642ef875e6e1af34dbf1bedd','source_contract_revision','massive-minute-aapl-20260908-v1','massive_minute_bundle_sha256',bundle);
 tid:=population_top3000_202608_202609_v1.pipeline_enqueue_v1('P01','ACQUIRE','massive-minute-AAPL-20260908-v1','{"kind":"MASSIVE_MINUTE_PILOT_V1","source_symbol":"AAPL","trading_date":"2026-09-08","max_pages":1,"first_page_review_required":true,"provider_accuracy_verified":false}',vers);
 UPDATE population_top3000_202608_202609_v1.pipeline_task SET not_before='infinity' WHERE task_id=tid;
 INSERT INTO population_top3000_202608_202609_v1.pipeline_event(task_id,event,details) VALUES(tid,'MASSIVE_MINUTE_FIRST_PAGE_REGISTERED',jsonb_build_object('owner_fence',2,'stop_generation',0,'provider','Massive','minute_bundle_sha256',bundle,'worker_sha256','ccf92df047ed9af51fbb2830fd1772c0ba8615e4e7a09ee53194c36ca96cc8c2','symbol','AAPL','ny_date','2026-09-08','window_start_ms',1788840000000::bigint,'window_end_exclusive_ms',1788926400000::bigint,'url_end_inclusive_ms',1788926399999::bigint,'adjusted',false,'max_pages',1,'lifetime_page_ceiling',100,'max_archive_source_occurrences',50000,'maximum_initial_provider_requests',1,'max_response_bytes',8388608,'max_runtime_ms',45000,'compact_batch_rows',1000,'legacy_adapters_preserved',legacy_hashes,'p02_unchanged',true,'sip_feed_verified',false,'company_population_verified',false,'budget_increased',false,'requires_controller_release',true));
END $admit$;
COMMIT;
